"""Synthetic UAE-workplace sentences for TUNING and testing Decode (D41). Everything here is written or generated by the developers and marked
`synthetic=true`; none of it is real speech or a real message. L2-ARCTIC is never used for tuning.

    python eval/decode_synth.py      # writes data/decode/voice_synthetic.csv and data/decode/typed_synthetic.csv (deterministic)

voice_synthetic.csv   what a speech-to-text transcript might look like, for the voice safety net
    id, transcript, intended, accent, kind, target, slot, synthetic, note
    kind = risky   the transcript has a DIFFERENT REAL WORD at `target` where `intended` should be (a plausible STT slip; the wrong words were
                   chosen by hand, not derived from the decoder's own sound rules)
           control the transcript is correct (must not be changed or questioned)
           benign  a sentence where the transcript's word is real and right but resembles a domain word ("the barking dog is at the gate")
typed_synthetic.csv   messages typed by ear (accent swaps applied to clean sentences), for the typed-text decoder
    id, text_as_typed, intended_meaning, accent, changes, clarify_ok, synthetic, note
"""

from __future__ import annotations

import csv
import random
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "data" / "decode"

# intended word -> plausible wrong REAL words a recogniser could write (hand-written)
CONFUSIONS = {
    "place": {
        "parking": ["barking", "marking", "packing"], "gate": ["date", "gait", "game"], "floor": ["flour", "flower", "four"],
        "building": ["billing", "bidding"], "tower": ["power", "towel"], "villa": ["fella", "vela"], "flat": ["fat", "flap", "flag"],
        "lift": ["left", "lit", "list"], "stairs": ["stares", "stars"], "mall": ["ball", "wall", "mole"], "station": ["nation", "stations"],
        "basement": ["placement", "casement"], "reception": ["perception", "deception"], "road": ["load", "rode"], "house": ["horse", "mouse", "hose"],
        "hotel": ["motel", "hostel"], "kitchen": ["chicken"], "room": ["broom", "zoom"], "door": ["dorm", "floor"], "office": ["offers", "officer"],
    },
    "number": {"three": ["free", "tree"], "nine": ["line", "mine", "nice"], "eight": ["ate", "eat"], "ten": ["then", "tan"], "twenty": ["plenty"],
               "fifteen": ["fifty"], "fifty": ["fifteen"], "six": ["sick", "six"], "seven": ["heaven", "several"]},
    "thing": {"bags": ["backs", "bugs", "bass"], "keys": ["cheese", "peas"], "water": ["waiter"], "food": ["foot", "fool"], "box": ["books", "bus", "boss"],
              "phone": ["foam", "bone"], "papers": ["pepper", "paper"], "files": ["miles", "fires", "flies"], "tools": ["pools", "fools"], "car": ["care", "core"],
              "parcel": ["partial", "pastel"], "helmet": ["helped"], "gloves": ["loves"], "uniform": ["informed"]},
    "time": {"morning": ["mourning"], "night": ["light", "knight", "might"], "noon": ["moon", "soon"], "evening": ["even in"], "tonight": ["tonight"]},
}
OPENERS = ["", "", "", "yalla", "habibi", "please", "listen", "ok", "hello"]
ACCENTS = ["ar", "hi", "ml", "tl", None]

WHERE_T = ["come to the {w}", "wait at the {w}", "meet me at the {w}", "go to the {w} now", "park near the {w}", "wait inside the {w}",
           "the truck is behind the {w}", "come from the {w}", "please wait outside the {w}", "deliver the box to the {w}"]
NUMBER_T = ["gate {w}", "come to gate {w}", "take the lift to floor {w}", "flat {w} please", "meet me at room {w}", "building {w} is closed"]
THING_T = ["bring the {w}", "take the {w} to the office", "please carry the {w}", "deliver the {w} today", "collect the {w} from the store"]
TIME_T = ["come tomorrow {w}", "call me before {w}", "wait until {w}", "come every {w}"]
AMOUNT_T = ["pay {w} dirhams", "it costs {w} dirhams"]

GENERIC_PLACES = ["corner", "workshop", "shade", "counter", "entrance", "yard", "site", "shelf", "desk", "meeting", "canteen", "garden", "cabin"]
FUNCTION_CONTROLS = [  # correct workplace sentences where a pronoun or other function word sits right after a preposition
    "wait for them at the gate", "call me before we start", "what is in it", "give it to him at the office", "since then the lift is closed",
    "i will be at work until five", "he is in it for the money", "we are at the mall now", "come with us to the parking", "the key is in you bag",
    "she said it before he came", "they are near us", "put it on them", "what did you say to me", "who is at the door",
]
BENIGN = [
    "the barking dog is at the gate", "the dog was barking at the gate", "he is parking the car", "the parking is full today", "stop barking please",
    "my flat is on the third floor", "the flour is in the kitchen", "the power is off in the building", "he left the keys in the lift",
    "the date is on the paper", "i am flying to dubai tomorrow", "she is happy today", "the food is ready", "close the door quietly",
    "the fire is out", "we are late for the meeting", "the boss said no", "he said he will come later", "have a good evening",
]


def _fill(rng: random.Random, kind: str, intended: str, wrong: str | None) -> tuple[str, str, str]:
    templates = {"place": WHERE_T, "number": NUMBER_T, "thing": THING_T, "time": TIME_T}[kind]
    t = rng.choice(templates)
    opener = rng.choice(OPENERS)
    pre = (opener + " ") if opener else ""
    return pre + t.format(w=wrong or intended), pre + t.format(w=intended), t


def build_voice() -> list[dict]:
    rng = random.Random(41)
    rows: list[dict] = []
    n = 0

    def add(kind, transcript, intended, accent, target, slot, note=""):
        nonlocal n
        n += 1
        rows.append({"id": f"vs{n:04d}", "transcript": transcript.strip(), "intended": intended.strip(), "accent": accent or "none", "kind": kind,
                     "target": target, "slot": slot, "synthetic": "true", "note": note})

    for cat, table in CONFUSIONS.items():
        for intended, wrongs in table.items():
            for wrong in wrongs:
                if wrong == intended or " " in wrong:
                    continue
                for _ in range(2):
                    acc = rng.choice(ACCENTS)
                    tr, gold, _tmpl = _fill(rng, cat, intended, wrong)
                    add("risky", tr, gold, acc, wrong, cat, f"{intended} written as {wrong}")
    for cat, table in CONFUSIONS.items():  # controls: the same words, correctly transcribed
        for intended in table:
            for _ in range(2):
                acc = rng.choice(ACCENTS)
                tr, gold, _ = _fill(rng, cat, intended, None)
                add("control", tr, gold, acc, intended, cat, "correct")
    for w in GENERIC_PLACES:  # correct sentences whose slot word is an ordinary word not in the domain lists
        for t in rng.sample(WHERE_T, 3):
            acc = rng.choice(ACCENTS)
            s = t.format(w=w)
            add("control", s, s, acc, w, "place", "generic word in a place slot")
    for w in ["five", "four", "nine", "two", "twelve", "eleven", "twenty", "hundred"]:
        for t in AMOUNT_T + ["come at {w} o'clock", "meet me at {w}", "gate {w}"]:
            acc = rng.choice(ACCENTS)
            s = t.format(w=w)
            add("control", s, s, acc, w, "number", "number word, correct")
    for s in BENIGN:
        for acc in ("ar", None):
            add("benign", s, s, acc, "", "", "real word that resembles a domain word, in a non-critical position")
    for s in FUNCTION_CONTROLS:
        for acc in ("ar", "hi", None):
            add("control", s, s, acc, "", "function", "a function word after a preposition must not be questioned")
    for s in ["don't come to the parking now", "do not bring the bags", "never park near the gate", "no parking here please", "he is not at the office",
              "please do not open the door", "we cannot wait for the lift"]:
        add("control", s, s, "ar", "", "negation", "negation must survive")
    return rows


# ---- typed by ear -------------------------------------------------------------------------------------------------------------------------

TYPED_SENTENCES = [
    "come to the parking gate three", "bring the pepsi from the fridge", "very good come at five", "wait at the basement near the lift",
    "the flat number is nine on the third floor", "please deliver the parcel to the reception", "meet me at the metro station tomorrow",
    "do not come to the parking now", "pay fifty dirhams tomorrow", "call me before six in the evening", "take the bags to the villa",
    "park near the building", "the lobby is closed today", "wait for me at the mall", "bring the keys to the office",
]
SPELLING = {
    "ar": [("p", "b"), ("v", "f")], "hi": [("v", "w"), ("w", "v")], "ml": [("z", "s")], "tl": [("f", "p"), ("v", "b")], "common": [("th", "t"), ("th", "d")],
}


TRICKY_TYPED_CONTROLS = [
    "the barking dog is at the gate", "plant a tree near the gate", "he plays the fife in the band", "the den is dark", "put it in the bin",
    "the tin is empty", "this is the third floor", "they are at the mall", "the bus is near the station", "we live in the villa",
    "the boss is at the office", "please keep the door open", "wait for the bell", "the tank is full", "he paid the bill",
    "the wall is wet", "take the bag to the van", "the fan is not working", "they will come tomorrow", "i will pay you on friday",
]


def _apply(sentence: str, swaps: list[tuple[str, str]], rng: random.Random) -> tuple[str, list[str]]:
    """Type a clean sentence 'by ear': apply the first applicable swap(s) to 1-2 words. Returns (typed, [intended->typed words])."""
    words = sentence.split()
    idxs = [i for i, w in enumerate(words) if any(meant in w for meant, _ in swaps)]
    rng.shuffle(idxs)
    changed = []
    for i in idxs[: rng.choice([1, 1, 2])]:
        for meant, heard in swaps:
            if meant in words[i]:
                new = words[i].replace(meant, heard, 1)
                if new != words[i]:
                    changed.append(f"{words[i]}->{new}")
                    words[i] = new
                    break
    return " ".join(words), changed


def build_typed() -> list[dict]:
    rng = random.Random(42)
    rows, n = [], 0
    for accent in ["ar", "hi", "ml", "tl"]:
        pack = SPELLING[accent] + SPELLING["common"]
        for s in TYPED_SENTENCES:
            typed, changed = _apply(s, pack, rng)
            if not changed:
                continue
            n += 1
            rows.append({"id": f"ts{n:04d}", "text_as_typed": typed, "intended_meaning": s, "accent": accent, "changes": "; ".join(changed),
                         "clarify_ok": "true", "synthetic": "true", "note": "accent swaps applied to a clean sentence"})
    for s in TRICKY_TYPED_CONTROLS:  # real words that look like accent respellings, typed correctly
        for acc in ("ar", "hi"):
            n += 1
            rows.append({"id": f"ts{n:04d}", "text_as_typed": s, "intended_meaning": s, "accent": acc, "changes": "", "clarify_ok": "false",
                         "synthetic": "true", "note": "tricky control: a real word that resembles a respelling"})
    for s in TYPED_SENTENCES:  # controls: typed correctly
        n += 1
        rows.append({"id": f"ts{n:04d}", "text_as_typed": s, "intended_meaning": s, "accent": "none", "changes": "", "clarify_ok": "false",
                     "synthetic": "true", "note": "typed correctly: must not be changed"})
    return rows


def write(path: Path, rows: list[dict]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8", newline="") as f:
        w = csv.DictWriter(f, fieldnames=list(rows[0]))
        w.writeheader()
        w.writerows(rows)


def main() -> None:
    voice, typed = build_voice(), build_typed()
    write(OUT / "voice_synthetic.csv", voice)
    write(OUT / "typed_synthetic.csv", typed)
    kinds = {k: sum(1 for r in voice if r["kind"] == k) for k in ("risky", "control", "benign")}
    print(f"voice_synthetic.csv: {len(voice)} rows {kinds}; typed_synthetic.csv: {len(typed)} rows")


if __name__ == "__main__":
    main()
